//! Integration under explicitly retained event outcomes; not a failure census.
mod io;
use quantum_ecc::{circuit::{Op,OperationType as K},sim::Simulator};
use sha3::{Shake256,Sha3_256,Digest,digest::{Update,ExtendableOutput,XofReader}};
use std::collections::BTreeSet;
const NO:u64=u64::MAX;
fn rng(label:&str,batch:u64)->impl XofReader{let mut h=Shake256::default();Update::update(&mut h,label.as_bytes());Update::update(&mut h,&batch.to_le_bytes());h.finalize_xof()}
fn word(r:&mut impl XofReader)->u64{let mut x=[0;8];r.read(&mut x);u64::from_le_bytes(x)}
fn hash(v:&[Op])->String{let mut h=Sha3_256::new();for o in v{for x in [o.kind as u64,o.q_control2.0,o.q_control1.0,o.q_target.0,o.c_target.0,o.c_condition.0,o.r_target.0]{Digest::update(&mut h,x.to_le_bytes());}}format!("{:x}",h.finalize())}
fn dims(v:&[Op])->(usize,usize){let q=v.iter().flat_map(|o|[o.q_control1.0,o.q_control2.0,o.q_target.0]).filter(|&q|q!=NO).max().unwrap_or(0)as usize+1;let b=v.iter().flat_map(|o|[o.c_condition.0,o.c_target.0]).filter(|&q|q!=NO).max().unwrap_or(0)as usize+1;(q,b)}
struct Bytes{data:Vec<u8>,at:usize}impl XofReader for Bytes{fn read(&mut self,out:&mut[u8]){let end=self.at.checked_add(out.len()).unwrap();assert!(end<=self.data.len());out.copy_from_slice(&self.data[self.at..end]);self.at=end;}}
fn validate_map(map:&[u32],old:usize){let mut prev=None;for &m in map{assert!((m as usize)<old);assert!(prev.map_or(true,|p|p<m));prev=Some(m);}}
fn select_bytes(data:&[u8],map:&[u32],old:usize)->Vec<u8>{validate_map(map,old);assert_eq!(data.len(),old*8+64);let mut out=vec![];for &m in map{out.extend_from_slice(&data[m as usize*8..m as usize*8+8]);}out.extend_from_slice(&data[old*8..]);out}
fn run(v:&[Op],bytes:Vec<u8>,input:&[(bool,usize,u64)],phase:u64,d:(usize,usize))->(Vec<u64>,Vec<u64>,u64,u64,[u8;64]){let mut r=Bytes{data:bytes,at:0};let mut s=Simulator::new(d.0,d.1,&mut r);s.phase=phase;for &(q,i,x)in input{if q{s.qubits[i]=x}else{s.bits[i]=x}}s.apply_iter(v.iter());let state=(s.qubits.clone(),s.bits.clone(),s.phase,s.stats.toffoli_gates);drop(s);let mut after=[0;64];r.read(&mut after);assert_eq!(r.at,r.data.len());(state.0,state.1,state.2,state.3,after)}
fn main(){let a:Vec<_>=std::env::args().collect();assert_eq!(a.len(),7);let old=io::load_ops(&a[1]);let edited=io::load_ops(&a[2]);let colored=io::load_ops(&a[3]);let manifest:serde_json::Value=serde_json::from_str(&std::fs::read_to_string(&a[5]).unwrap()).unwrap();let map_raw=std::fs::read(&a[4]).unwrap();assert_eq!(&map_raw[..8],b"RNGSUBS1");let count=u64::from_le_bytes(map_raw[8..16].try_into().unwrap())as usize;let new_count=u64::from_le_bytes(map_raw[16..24].try_into().unwrap())as usize;assert_eq!(map_raw.len(),88+4*new_count);let input_hash=hash(&old);assert_eq!(&map_raw[24..88],input_hash.as_bytes());assert_eq!(manifest["input_full_sha3_256"],input_hash);assert_eq!(manifest["output_full_sha3_256"],hash(&edited));let map:Vec<_>=map_raw[88..].chunks_exact(4).map(|x|u32::from_le_bytes(x.try_into().unwrap())).collect();validate_map(&map,count);
 let events:Vec<_>=old.iter().enumerate().filter(|(_,o)|matches!(o.kind,K::R|K::Hmr)).collect();let new_events:Vec<_>=edited.iter().filter(|o|matches!(o.kind,K::R|K::Hmr)).collect();assert_eq!(events.len(),count);assert_eq!(new_events.len(),new_count);for(j,&m)in map.iter().enumerate(){assert_eq!(events[m as usize].1,new_events[j]);}
 let removed:BTreeSet<_>=manifest["sites"].as_array().unwrap().iter().map(|s|s["removed_Hmr"].as_u64().unwrap()as usize).collect();let retained:BTreeSet<_>=map.iter().copied().collect();let missing:BTreeSet<_>=events.iter().enumerate().filter(|(j,_)|!retained.contains(&(*j as u32))).map(|(_,x)|x.0).collect();assert_eq!(missing,removed);assert_eq!(colored.iter().filter(|o|matches!(o.kind,K::R|K::Hmr)).count(),new_count);
 let private:BTreeSet<_>=manifest["sites"].as_array().unwrap().iter().map(|s|s["removed_bit"].as_u64().unwrap()as usize).collect();let registered:BTreeSet<_>=old.iter().filter(|o|o.kind==K::AppendToRegister&&o.q_target.0!=NO).map(|o|o.q_target.0 as usize).collect();let regbits:BTreeSet<_>=old.iter().filter(|o|o.kind==K::AppendToRegister&&o.c_target.0!=NO).map(|o|o.c_target.0 as usize).collect();assert!(regbits.is_disjoint(&private));let saved=manifest["parity_zero_products_removed"].as_u64().unwrap()*64;let d=dims(&old);assert!(dims(&edited).0<=d.0&&dims(&colored).0<=d.0);let mut rows=vec![];
 for batch in 0..8{let mut ir=rng("and-target-control-uniform-raw-inputs-20261019",batch);let mut input=vec![];let mut seen=BTreeSet::new();for o in &old{if o.kind==K::AppendToRegister{for(q,i)in [(true,o.q_target.0),(false,o.c_target.0)]{if i!=NO&&seen.insert((q,i)){input.push((q,i as usize,word(&mut ir)));}}}}let phase=word(&mut ir);let mut physical=rng("and-target-control-retained-events-20261019",batch);let mut data=vec![0;count*8+64];physical.read(&mut data);let mapped=select_bytes(&data,&map,count);let x=run(&old,data,&input,phase,d);let y=run(&edited,mapped.clone(),&input,phase,d);assert_eq!(x.0,y.0,"all original quantum wires");for b in 0..d.1{if !private.contains(&b){assert_eq!(x.1[b],y.1[b],"observable classical bit {b}");}}assert_eq!(x.2,y.2,"phase");assert_eq!(x.3,y.3+saved,"exact executed Toffolis");assert_eq!(x.4,y.4,"event continuation");let z=run(&colored,mapped,&input,phase,d);assert_eq!(y.1,z.1,"allocator classical bits");assert_eq!(y.2,z.2,"allocator phase");assert_eq!(y.3,z.3,"allocator Toffolis");assert_eq!(y.4,z.4,"allocator continuation");for &q in &registered{assert_eq!(y.0[q],z.0[q],"registered output");}let scratch=|s:&Vec<u64>|{let mut v:Vec<_>=s.iter().enumerate().filter(|(q,_)|!registered.contains(q)).map(|(_,x)|*x).collect();v.sort_unstable();v};assert_eq!(scratch(&y.0),scratch(&z.0));rows.push(serde_json::json!({"batch":batch,"shots":64,"all_original_quantum_outputs_phase_and_observable_classical_equal":true,"allocator_transcript_equal":true,"executed_Toffolis_saved_per_64_shots":saved}));}
 let result=serde_json::json!({"status":"PROTECTED_SIMULATOR_EVENT_SUBSEQUENCE_CONTROL_PASS","scope":"512 raw assignments, retained event outcomes; not ordinary physical-RNG coupling, no statistical gate or score","input_sha3_256":input_hash,"edited_sha3_256":hash(&edited),"colored_sha3_256":hash(&colored),"rng_map_sha3_256":format!("{:x}",Sha3_256::digest(&map_raw)),"original_rng_events":count,"remaining_rng_events":new_count,"removed_private_bit_slots":private.len(),"original_Q":d.0,"colored_Q":dims(&colored).0,"rows":rows});std::fs::write(&a[6],serde_json::to_string_pretty(&result).unwrap()).unwrap();println!("eight full protected subsequence controls pass");}
#[cfg(test)]mod tests{use super::*;
 #[test]fn subsequence_preserves_whole_event_words_and_final_continuation(){let v:Vec<_>=(0..88).collect();let out=select_bytes(&v,&[0,2],3);assert_eq!(&out[..8],&v[..8]);assert_eq!(&out[8..16],&v[16..24]);assert_eq!(&out[16..],&v[24..]);}
 #[test]#[should_panic]fn duplicate_event_rejected(){validate_map(&[1,1],3);}
 #[test]#[should_panic]fn reordered_event_rejected(){validate_map(&[2,1],3);}
 #[test]#[should_panic]fn out_of_range_event_rejected(){validate_map(&[0,3],3);}
 #[test]fn zero_remaining_events_keep_continuation(){assert_eq!(select_bytes(&[1;72],&[],1),vec![1;64]);}
}
